#include <iostream>       // For input/output operations
#include <fstream>        // For file handling operations
#include <vector>         // For using vector container
#include <iomanip>        // For formatting output
using namespace std;

// Class to represent a Student
class Student {
private:
    int id;               // Student ID
    string name;          // Student name
    float marks;          // Student marks

public:
    // Constructor to initialize student data
    Student(int i, string n, float m) {
        id = i;
        name = n;
        marks = m;
    }

    // Method to display student information in formatted way
    void display() const {
        cout << left << setw(10) << id
             << setw(20) << name
             << setw(10) << marks << endl;
    }

    // Getter method for student ID
    int getId() const {
        return id;
    }

    // Getter method for student name
    string getName() const {
        return name;
    }

    // Getter method for student marks
    float getMarks() const {
        return marks;
    }
};

// Function to save student records to a file
void saveToFile(const vector<Student>& students) {
    // Create/open file named "students.txt"
    ofstream file("students.txt");

    // Check if file opened successfully
    if (!file) {
        cout << "Error opening file!" << endl;
        return;
    }

    // Write each student's data to the file
    for (const auto& student : students) {
        file << student.getId() << " "
             << student.getName() << " "
             << student.getMarks() << endl;
    }

    file.close();  // Close the file
}

// Function to find and display the student with highest marks
void displayTopper(const vector<Student>& students) {
    // Check if vector is empty
    if (students.empty()) {
        cout << "No student records found." << endl;
        return;
    }

    // Assume first student is the topper initially
    Student topper = students[0];

    // Compare marks of all students to find the topper
    for (const auto& student : students) {
        if (student.getMarks() > topper.getMarks()) {
            topper = student;
        }
    }

    // Display the topper's information
    cout << "\nTop Performing Student\n";
    cout << "----------------------\n";
    topper.display();
}

int main() {
    // Create a vector to store Student objects
    vector<Student> students;

    // Add student records to the vector
    students.push_back(Student(101, "Ali", 87.5));
    students.push_back(Student(102, "Sara", 92.0));
    students.push_back(Student(103, "Ahmed", 78.4));
    students.push_back(Student(104, "Ayesha", 95.6));

    // Display table header
    cout << left << setw(10) << "ID"
         << setw(20) << "Name"
         << setw(10) << "Marks" << endl;

    cout << "--------------------------------------\n";

    // Display all student records
    for (const auto& student : students) {
        student.display();
    }

    // Find and display the topper
    displayTopper(students);

    // Save records to file
    saveToFile(students);

    cout << "\nStudent records saved successfully." << endl;

    return 0;
}
